{
  "requirement_definitions": [
    {
      "id": "DMSR-2104",
      "title": "Guider Calibration Data Acquisition",
      "text": "The DMS shall acquire raw, full-frame exposures from the camera guider sensors during calibration. The DMS shall produce calibration data products for the guide sensors."
    },
    {
      "id": "DMSR-7154",
      "title": "Nightly Data Accessible Within Speciﬁed Time",
      "text": "With the exception of alerts and Solar System Objects, all Level 1 Data Products shall be made public within time L1PublicT of the acquisition of the raw image data. LSST shall not release image or catalog data resulting from a visit, except for the content of the public alert stream, sooner than time L1PublicTMin following the acquisition of the raw image data from that visit. For visits resulting in fewer than nAlertVisitPeak, LSST shall be capable of supporting the distribution of at least OTR1 per cent of alerts via the LSST alert distribution system within time OTT1 from the conclusion of the camera’s readout of the raw exposures used to generate each alert. Solar System Object orbits will, on average, be calculated before the following night’s observing ﬁnishes and the results shall be made available within time L1PublicT of those calculations being completed."
    },
    {
      "id": "DMSR-4041",
      "title": "Processed Visit Images",
      "text": "The DMS shall produce Processed Visit Images, in which the corresponding raw sensor array data has been trimmed of overscan and corrected for instrumental signature. Images obtained in pairs during a standard visit are combined."
    },
    {
      "id": "DMSR-5758",
      "title": "Background Model Calculation",
      "text": "The DMS shall derive and persist a background model (both due to night sky and astrophysical) for each visit image, per CCD."
    },
    {
      "id": "DMSR-4744",
      "title": "Generate Photometric Zeropoint for Visit Image",
      "text": "The DMS shall derive and persist a photometric zeropoint for each visit image, per CCD."
    },
    {
      "id": "DMSR-1714",
      "title": "Generate PSF for Visit Images",
      "text": "The DMS shall determine a characterization of the PSF for any speciﬁed location in Processed Visit Images."
    },
    {
      "id": "DMSR-2295",
      "title": "Generate WCS for Visit Images",
      "text": "The DMS shall generate and persist a WCS for each visit image. The absolute accuracy of the WCS shall be at least astrometricAccuracy in all areas of the image, provided that there are at least astrometricMinStandards astrometric standards available in each CCD."
    }
  ],
  "allocation_entries": []
}
